  Q11616639: {"name": "神宮寺（小浜市）", "official": "https://wakasa-obama.jp/spot/jinguji/", "address": "福井県小浜市神宮寺30-4", "hours": "9:00～16:00（2月15日～3月5日はお水送りの準備のため拝観不可）", "fee": "500円", "access": "JR東小浜駅から車で10分。舞鶴若狭自動車道 小浜ICから車で15分", "notes": "天台宗。和銅7年(714)創建と伝わる神仏習合の寺で、本堂にしめ縄、内陣に神棚がある。毎年3月2日に東大寺二月堂へ香水を送る「お水送り」を行う", "sources": [["神宮寺（若狭おばま観光協会）", "https://wakasa-obama.jp/spot/jinguji/"]], "checked": "2026-11-04"},
  Q11434131: {"name": "大塩八幡宮", "official": "https://oosiohatiman.wixsite.com/oosiohatiman/", "address": "福井県越前市国兼町22-2", "access": "ハピライン武生駅から車で15分。北陸自動車道 武生ICから車で15分。駐車場なし", "notes": "御朱印 8:30～18:00（社務所）。拝殿は国の重要文化財。仁和3年(887)に紀友仲が祈願し、のちに社殿を建てたと伝わる。木曽義仲が本陣を置いたという話も残る", "sources": [["大塩八幡宮（ふくいドットコム／福井県公式観光サイト）", "https://www.fuku-e.com/spot/detail_1045.html"]], "checked": "2026-11-04"},
  Q11352377: {"name": "一乗滝", "official": "https://fuku-iro.jp/spot/detail_10146.html", "address": "福井県福井市浄教寺町", "hours": "見学自由", "fee": "無料", "access": "JR福井駅から京福バス浄教寺行きで終点「浄教寺」下車、徒歩20分。車は北陸自動車道 福井ICから15分。駐車場あり", "notes": "落差17m。一乗谷川の上流にあり、泰澄大師ゆかりの地。佐々木小次郎が燕返しを編み出したと伝わる", "sources": [["一乗滝（福いろ／福井市公式観光サイト）", "https://fuku-iro.jp/spot/detail_10146.html"]], "checked": "2026-11-04"},
  Q11401286: {"name": "北口本宮冨士浅間神社", "official": "https://www.sengenjinja.jp/", "address": "山梨県富士吉田市上吉田5558", "access": "富士急行線富士山駅から徒歩20分、またはバスで「浅間神社前」下車すぐ。車は中央自動車道 河口湖ICから約3km（約10分）。無料駐車場あり", "deities": ["木花開耶姫命（主祭神）"], "notes": "祈祷受付 9:00～16:00頃（夏季延長あり）。年中無休。富士山の世界遺産構成資産のひとつ。木造で日本最大級の「冨士山大鳥居」、樹齢約1000年の冨士太郎杉・夫婦ヒノキがある。7月1日お山開き、8月26・27日吉田の火祭り", "sources": [["交通案内（北口本宮冨士浅間神社 公式）", "https://www.sengenjinja.jp/access/index.html"], ["北口本宮冨士浅間神社（富士の国やまなし観光ネット）", "https://www.yamanashi-kankou.jp/kankou/spot/p1_8016.html"], ["北口本宮冨士浅間神社（富士吉田市観光ガイド）", "https://fujiyoshida.net/spot/23"]], "checked": "2026-11-04"},
  Q712162: {"name": "久能山東照宮", "official": "https://www.toshogu.or.jp/", "address": "静岡県静岡市駿河区根古屋390", "hours": "9:00～17:00（年中無休、受付は終了10分前まで）", "fee": "社殿 大人700円・小中学生300円／博物館との共通券 大人1,200円・小中学生500円", "access": "JR静岡駅からバスで日本平ロープウェイへ（約45分）、ロープウェイ約5分。または久能山下から石段1,159段（登り約20分）。山上へ車で上がる道はなし", "notes": "日本平ロープウェイは往復 大人1,250円。日本平山頂に無料駐車場200台。", "sources": [["交通案内｜久能山東照宮（公式）", "https://www.toshogu.or.jp/access/"], ["拝観料のご案内｜久能山東照宮（公式）", "https://www.toshogu.or.jp/worship/fees.php"]], "checked": "2026-11-04"},
